def parser(log: str) -> dict[str, str]:
    import re
    from xml.etree import ElementTree as ET

    results: dict[str, str] = {}

    def set_status(test_id: str, status: str):
        prev = results.get(test_id)
        if prev == "fail":
            return
        if prev == "skip" and status == "pass":
            return
        results[test_id] = status

    # Parse Surefire XML <testsuite> blocks
    for m in re.finditer(r'(<testsuite\b.*?</testsuite>)', log, re.DOTALL | re.IGNORECASE):
        xml_text = m.group(1)
        try:
            root = ET.fromstring(xml_text)
        except Exception:
            continue
        for tc in root.findall(".//testcase"):
            classname = tc.get("classname") or ""
            name = tc.get("name") or ""
            test_id = f"{classname}#{name}" if classname else name
            status = "pass"
            if tc.find("failure") is not None or tc.find("error") is not None:
                status = "fail"
            elif tc.find("skipped") is not None:
                status = "skip"
            if test_id:
                set_status(test_id, status)

    # Fallback parsing for Maven console failure/error lines
    fail_err_re = re.compile(
        r'^\s*([A-Za-z0-9_$.]+)\.([A-Za-z0-9_<>$\[\]\-()]+)\s+--.*?<<<\s*(FAILURE|ERROR)!',
        re.MULTILINE
    )
    for mm in fail_err_re.finditer(log):
        cls, method, _ = mm.groups()
        set_status(f"{cls}#{method}", "fail")

    # Fallback for shortened error summaries: "[ERROR]   Class.method:line ..."
    short_fail_re = re.compile(
